def supports_mamba_cache_extra_buffer(view: Any, hf_config: Any) -> bool:
    """Whether the model of ``hf_config`` supports the extra_buffer strategy on
    the configured linear-attention backend (pure read)."""
    from sglang.srt.configs.linear_attn_model_registry import get_linear_attn_spec

    spec = get_linear_attn_spec(hf_config)
    if hf_config.architectures[0] in _MAMBA_EXTRA_BUFFER_ARCHS or (
        spec is not None and spec.support_mamba_cache_extra_buffer
    ):
        return view.linear_attn_backend == "triton"
    return False


@register_post_process
def _mamba_radix_cache_resolution(view: Any) -> dict:
    """Resolve hybrid-Mamba cache settings using the current page size and overlap policy."""
    from sglang.srt.configs.linear_attn_model_registry import get_linear_attn_spec

    hf_config = model_config_of(view).hf_config
    model_arch = hf_config.architectures[0]

    in_branch = model_arch in _MAMBA_RADIX_CACHE_ARCHS
    if model_arch == "GraniteMoeHybridForCausalLM":
        in_branch = any(
            layer_type == "mamba"
            for layer_type in getattr(hf_config, "layer_types", [])
        )
    # Specs registered by config predicate (archs=[]) are only reachable
    # through the HF config, not the architecture name.
    spec = get_linear_attn_spec(hf_config)
    if not ((spec is not None and spec.uses_mamba_radix_cache) or in_branch):
        return {}

    if view.disable_radix_cache:
        return {}

    declared: Dict[str, Any] = {"uses_mamba_radix_cache": True}
    if view.mamba_radix_cache_strategy == "auto":
        wants_overlap = not view.disable_overlap_schedule
        wants_paging = view.page_size is not None and view.page_size > 1
        if (wants_overlap or wants_paging) and supports_mamba_cache_extra_buffer(
            view, hf_config
        ):
            declared["mamba_radix_cache_strategy"] = "extra_buffer"
        else:
            declared["mamba_radix_cache_strategy"] = "no_buffer"
            declared["disable_overlap_schedule"] = True
    return declared


@register_post_process
def _dsa_kv_cache_dtype_default(view: Any) -> dict:
    """Default DSA KV-cache dtype before resolving split attention backends."""
    from sglang.srt.configs.model_config import is_deepseek_dsa, is_kimi_k31

    hf_config = model_config_of(view).hf_config
    kimi_k31 = is_kimi_k31(hf_config)
    if hf_config.architectures[0] not in _DEEPSEEK_FAMILY_ARCHS and not kimi_k31:
        return {}
    if not is_deepseek_dsa(hf_config):
        return {}
    if get_platform().is_npu:
        return {}
    if get_platform().is_xpu:
        if view.kv_cache_dtype == "auto":
            logger.warning(
                "Setting KV cache dtype to bfloat16 for DeepSeek DSA on XPU."
            )
            return {"kv_cache_dtype": "bfloat16"}
        return {}

    if kimi_k31:
        return _kimi_k31_kv_cache_dtype(view)

    import torch

    major, _ = torch.cuda.get_device_capability()

    # If user specified a backend but didn't explicitly set kv_cache_dtype,
    # suggest them to be explicit about kv_cache_dtype to avoid surprises
    if (
        view.dsa_prefill_backend is not None or view.dsa_decode_backend is not None
    ) and view.kv_cache_dtype == "auto":
        logger.warning(
            "When specifying --dsa-prefill-backend or --dsa-decode-backend, "
            "you should also explicitly set --kv-cache-dtype (e.g., 'fp8_e4m3' or 'bfloat16'). "
            "DeepSeek V3.2 defaults to FP8 KV cache which may not be compatible with all backends."
        )

    kv_cache_dtype = view.kv_cache_dtype
    has_attention_sinks = bool(getattr(hf_config, "learnable_sink", False))
    if has_attention_sinks and kv_cache_dtype not in ("auto", "bf16", "bfloat16"):
        raise ValueError(
            "Learnable DSA attention sinks require a bfloat16 KV cache; "
            f"got kv_cache_dtype={kv_cache_dtype}."
        )
    if kv_cache_dtype == "auto":
        # gfx950 reports capability 9.x, but its triton/tilelang DSA kernels
        # take fp8 KV and the gfx950-tuned sparse-MLA path requires it. The raw
        # fp8 MLA layout is only read back on the aiter path (forward_mha.py).
        hip_gfx95_fp8 = (
            get_platform().is_hip
            and is_gfx95_supported()
            and envs.SGLANG_USE_AITER.get()
            and view.dsa_prefill_backend in (None, "triton", "tilelang")
            and view.dsa_decode_backend in (None, "triton", "tilelang")
        )
        kv_cache_dtype = (
            "fp8_e4m3"
            if (major >= 10 or hip_gfx95_fp8) and not has_attention_sinks
            else "bfloat16"
        )
        logger.warning(
            f"Setting KV cache dtype to {kv_cache_dtype} for DeepSeek DSA "
            f"(device capability major {major})."
        )
    if kv_cache_dtype == "bf16":
        kv_cache_dtype = "bfloat16"
    assert kv_cache_dtype in [
        "bfloat16",
        "fp8_e4m3",
    ], "DeepSeek DSA only supports bf16/bfloat16 or fp8_e4m3 kv_cache_dtype"
    if kv_cache_dtype != view.kv_cache_dtype:
        return {"kv_cache_dtype": kv_cache_dtype}
    return {}


def _check_dsa_backend_constraints(
    kv_cache_dtype: str,
    prefill_backend: Optional[str],
    decode_backend: Optional[str],
    *,
    hip: bool,
    dcp_size: int = 1,
) -> None:
    """Validate DSA backend / platform / kv-cache-dtype constraints."""
    chosen = {prefill_backend, decode_backend}

    # The SM100/SM103/SM107 check is check_prims_ts_sparse_mla_support, at backend init.
    if "prims_ts" in chosen and (hip or kv_cache_dtype != "fp8_e4m3"):
        raise ValueError(
            "The prims_ts DSA backend needs CUDA and --kv-cache-dtype fp8_e4m3."
        )

    rocm_only = {"triton"} & chosen
    if not hip and rocm_only:
        raise ValueError(
            f"The {'/'.join(sorted(rocm_only))} DSA backend is only supported on "
            "ROCm/HIP. Pick an alternative DSA backend for CUDA "
            "(flashmla_kv on Hopper, trtllm on Blackwell)."
        )

    if hip and dcp_size > 1:
        no_dcp_path = chosen - {"triton", None}
        if no_dcp_path:
            raise ValueError(
                f"The {'/'.join(sorted(no_dcp_path))} DSA backend has no DCP path "
                "on ROCm; use --dsa-prefill-backend triton --dsa-decode-backend "
                "triton with --dcp-size > 1."
            )

    if hip or kv_cache_dtype != "fp8_e4m3" or "tilelang" not in chosen:
        return
    if prefill_backend != "tilelang" or decode_backend != "tilelang":
        raise ValueError(
            "CUDA TileLang FP8 KV requires both DSA backends to be tilelang; "
            "raw and scaled FP8 KV layouts cannot be mixed."
        )
    if dcp_size > 1:
        raise ValueError("CUDA TileLang FP8 KV does not support --dcp-size > 1.")

    import torch

    major, minor = torch.cuda.get_device_capability()
    if (major, minor) < (8, 9):
        raise ValueError("CUDA TileLang FP8 KV requires SM89 or newer.")


def _check_tilelang_dsa_fp8_kv(
    kv_cache_dtype: str,
    prefill_backend: Optional[str],
    decode_backend: Optional[str],
    *,
    hip: bool,
    dcp_size: int = 1,
) -> None:
    """Backward-compatible entry point for the TileLang DSA validation."""
    _check_dsa_backend_constraints(
        kv_cache_dtype, prefill_backend, decode_backend, hip=hip, dcp_size=dcp_size
    )


@register_post_process
def _dsa_split_backend_resolution(view: Any) -> dict:
    """Resolve DSA split backends from KV-cache dtype and device capability.

    HiSparse settings take precedence when enabled.
    """
    from sglang.srt.configs.model_config import is_deepseek_dsa, is_kimi_k31

    hf_config = model_config_of(view).hf_config
    kimi_k31 = is_kimi_k31(hf_config)
    if hf_config.architectures[0] not in _DEEPSEEK_FAMILY_ARCHS and not kimi_k31:
        return {}
    if not is_deepseek_dsa(hf_config):
        return {}
    if get_platform().is_npu:
        return {}
    if get_platform().is_xpu:
        declared: Dict[str, Any] = {}
        if view.dsa_prefill_backend is None:
            declared["dsa_prefill_backend"] = "intel_xpu"
        if view.dsa_decode_backend is None:
            declared["dsa_decode_backend"] = "intel_xpu"
        logger.warning(
            "Set DSA backends for XPU: prefill=%s, decode=%s, topk=%s.",
            declared.get("dsa_prefill_backend", view.dsa_prefill_backend),
            declared.get("dsa_decode_backend", view.dsa_decode_backend),
            declared.get("dsa_topk_backend", view.dsa_topk_backend),
        )
        return declared

    import torch

    major, _ = torch.cuda.get_device_capability()
    if kimi_k31:
        return _kimi_k31_dsa_backends(view)

    kv_cache_dtype = view.kv_cache_dtype
    user_set_prefill = view.dsa_prefill_backend is not None
    user_set_decode = view.dsa_decode_backend is not None
    declared: Dict[str, Any] = {}
    model_arch = hf_config.architectures[0]
    is_glm_sm12_fp8 = (
        model_arch == "GlmMoeDsaForCausalLM"
        and major == 12
        and kv_cache_dtype == "fp8_e4m3"
        and not get_platform().is_hip
    )

    if getattr(hf_config, "learnable_sink", False):
        backend = "flashmla_sparse"
        declared = _pin_dsa_backends(
            view,
            backend,
            lambda option, value: (
                f"{model_arch} uses learnable attention sinks and requires "
                f"{option} {backend!r}; got {value!r}"
            ),
        )
        logger.warning(
            "Set DSA backends for learnable attention sinks: "
            f"prefill={declared.get('dsa_prefill_backend', view.dsa_prefill_backend)}, "
            f"decode={declared.get('dsa_decode_backend', view.dsa_decode_backend)}."
        )
        return declared

    if is_glm_sm12_fp8:
        backend = "flashinfer_sparse_mla"
        if not user_set_prefill:
            declared["dsa_prefill_backend"] = backend
        if not user_set_decode:
            declared["dsa_decode_backend"] = backend
        logger.warning(
            "Set DSA backends for GLM FP8 KV Cache on SM120/SM121: "
            f"prefill={backend}, decode={backend}."
        )
        return declared

    if view.enable_hisparse:
        from sglang.srt.arg_groups.hisparse_hook import _hisparse_default_backend

        backend = _hisparse_default_backend(kv_cache_dtype)
        if not user_set_prefill:
            declared["dsa_prefill_backend"] = backend
        if not user_set_decode:
            declared["dsa_decode_backend"] = backend
        prefill = declared.get("dsa_prefill_backend", view.dsa_prefill_backend)
        decode = declared.get("dsa_decode_backend", view.dsa_decode_backend)
        if (
            not get_platform().is_hip
            and kv_cache_dtype == "fp8_e4m3"
            and "tilelang" in (prefill, decode)
        ):
            raise ValueError("CUDA TileLang FP8 KV does not support HiSparse.")
        # The hisparse allow-list in hisparse_hook is platform- but not
        # dtype-aware, so an explicitly requested backend still has to clear the
        # shared backend/kv-cache-dtype rules before this arm returns early.
        _check_dsa_backend_constraints(
            kv_cache_dtype,
            prefill,
            decode,
            hip=get_platform().is_hip,
            dcp_size=getattr(view, "dcp_size", 1) or 1,
        )
        logger.warning(
            f"HiSparse enabled ({kv_cache_dtype}): using DSA backends "
            f"prefill={prefill}, decode={decode}."
        )
        return declared

    if get_platform().is_hip:
        if not user_set_prefill:
            declared["dsa_prefill_backend"] = "triton"
        if not user_set_decode:
            declared["dsa_decode_backend"] = "triton"
    elif kv_cache_dtype == "fp8_e4m3":
        # Blackwell FP8 defaults to trtllm; Hopper FP8 to flashmla_kv.
        default = "trtllm" if major >= 10 else "flashmla_kv"
        if not user_set_prefill:
            declared["dsa_prefill_backend"] = default
        if not user_set_decode:
            declared["dsa_decode_backend"] = default
    else:
        # Set prefill/decode backends based on hardware architecture.
        if not user_set_prefill:
            declared["dsa_prefill_backend"] = "flashmla_sparse"
        if not user_set_decode:
            declared["dsa_decode_backend"] = "trtllm" if major >= 10 else "fa3"

    prefill = declared.get("dsa_prefill_backend", view.dsa_prefill_backend)
    decode = declared.get("dsa_decode_backend", view.dsa_decode_backend)
    _check_dsa_backend_constraints(
        kv_cache_dtype,
        prefill,
        decode,
        hip=get_platform().is_hip,
        dcp_size=getattr(view, "dcp_size", 1) or 1,
    )
    logger.warning(
        f"Set DSA backends for {kv_cache_dtype} KV Cache: "
        f"prefill={prefill}, decode={decode}."
    )
    return declared


def _pin_dsa_backends(
    view: Any, backend: str, mismatch_error: Callable[[str, str], str]
) -> Dict[str, Any]:
    declared: Dict[str, Any] = {}
    for field in ("dsa_prefill_backend", "dsa_decode_backend"):
        value = getattr(view, field)
        if value is None:
            declared[field] = backend
        elif value != backend:
            option = "--" + field.replace("_", "-")
            raise ValueError(mismatch_error(option, value))
    return declared


# Matches the reference fp8_ds_mla cache; trtllm's 576 B layout does not.
_KIMI_K31_DSA_BACKEND = "flashmla_kv"
_KIMI_K31_DSA_BACKENDS = ("flashmla_kv", "trtllm", "prims_ts")
# ROCm: the Triton kernels dequantize the same fp8_ds_mla rows and run BF16 dots.
_KIMI_K31_DSA_BACKEND_HIP = "triton"


def _kimi_k31_kv_cache_dtype(view: Any) -> dict:
    if view.kv_cache_dtype not in ("auto", "fp8_e4m3"):
        raise ValueError(
            "Kimi-K3.1 requires --kv-cache-dtype fp8_e4m3 (the reference "
            f"fp8_ds_mla format); got {view.kv_cache_dtype!r}."
        )
    if view.kv_cache_dtype != "fp8_e4m3":
        logger.warning("Setting KV cache dtype to fp8_e4m3 for Kimi-K3.1.")
        return {"kv_cache_dtype": "fp8_e4m3"}
    return {}


def _kimi_k31_dsa_backends(view: Any) -> dict:
    if get_platform().is_hip:
        if view.enable_hisparse:
            raise ValueError(
                "Kimi-K3.1 does not support --enable-hisparse on ROCm yet."
            )
        backend = _KIMI_K31_DSA_BACKEND_HIP
        return _pin_dsa_backends(
            view,
            backend,
            lambda option, value: (
                f"Kimi-K3.1 requires {option} {backend!r} on ROCm; got {value!r}."
            ),
        )
    fields = ("dsa_prefill_backend", "dsa_decode_backend")
    for field in fields:
        value = getattr(view, field)
        if value is not None and value not in _KIMI_K31_DSA_BACKENDS:
            option = "--" + field.replace("_", "-")
            raise ValueError(
                f"Kimi-K3.1 supports {option} {' / '.join(_KIMI_K31_DSA_BACKENDS)}; "
                f"got {value!r}."
            )
    # Both phases read one KV pool (and PD peers exchange it), so an unset
    # phase follows the set one.
    chosen = {getattr(view, f) for f in fields} - {None}
    if len(chosen) > 1:
        raise ValueError(
            "Kimi-K3.1 needs the same --dsa-prefill-backend and "
            "--dsa-decode-backend (flashmla_kv and trtllm / prims_ts use "
            f"different KV layouts); got {view.dsa_prefill_backend!r} and "
            f"{view.dsa_decode_backend!r}."
        )
    backend = chosen.pop() if chosen else _KIMI_K31_DSA_BACKEND
    if backend in ("trtllm", "prims_ts"):
        logger.warning(
            f"Kimi-K3.1 {backend} DSA uses FP8 q and an unscaled FP8 KV cache, not "
            "the reference fp8_ds_mla numerics. PD prefill and decode servers must "
            "both use a raw-FP8-KV backend (trtllm or prims_ts)."
        )
    if view.enable_hisparse and backend != _KIMI_K31_DSA_BACKEND:
        # The HiSparse FP8 backend allow-list (hisparse_hook) admits only
        # flashmla_kv among the K3.1 backends.
        raise ValueError(
            f"Kimi-K3.1 HiSparse requires DSA backend {_KIMI_K31_DSA_BACKEND!r}; "
            f"got {backend!r}."
        )
    declared = {f: backend for f in fields if getattr(view, f) is None}
    logger.warning(
        "Set DSA backends for Kimi-K3.1: prefill=%s, decode=%s.", backend, backend
    )
    return declared


